export async function getNews({ filter, limit = 9, page = 1 }: Props) {
  try {
    let news: Query<NewsDocument<string>>;
    const client = createClient();

    if (filter === 'news' || !filter) {
      news = await client.getByType('news', {
        orderings: { field: 'my.news.date', direction: 'desc' },
        pageSize: limit,
        page,
      });
    } else if (filter === 'combat-sports') {
      news = await client.getByType('news', {
        filters: [prismicFilter.any('my.news.sports.sport', [...])],
        pageSize: limit,
        page,
      });
    } else {
      news = await client.getByType('news', {
        filters: [prismicFilter.at('my.news.sports.sport', ...)],
        pageSize: limit,
        page,
      });
    }
    return { news: news.results, totalPages: news.total_pages || 1 };
  } catch {
    return { news: [], totalPages: 1 };
  }
}
